mapper.select:
SELECT FROM ai_vendor v
AND v.vendor_name LIKE concat('%', #{vendorName}, '%') AND v.status = #{status}
ORDER BY v.is_default DESC, v.vendor_id ASC

mapper.update:
UPDATE ai_vendor
vendor_name = #{vendorName}, base_url = #{baseUrl}, api_key_cipher = #{apiKeyCipher}, api_key_mask = #{apiKeyMask}, model_name = #{modelName}, status = #{status}, timeout_sec = #{timeoutSec}, max_tokens = #{maxTokens}, temperature = #{temperature}, remark = #{remark}, update_by = #{updateBy}, update_time = NOW()
WHERE vendor_id = #{vendorId}
